# Completa la línea marcada y compruébala con py check.
import math

def asignar(punto, centros):
    mejor, mejor_d = 0, math.inf
    for i, c in enumerate(centros):
        d = math.sqrt(sum((x - y) ** 2 for x, y in zip(punto, c)))
        if d < mejor_d:
            mejor_d = d   # ← falta guardar también cuál es: mejor = i
    return mejor

print(asignar([0.9, 0.8], [[0.1, 0.2], [0.8, 0.7]]))   # 1
